import os, glob, re

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load()
print("Loaded grids:", sorted(G.keys()))
for k, v in G.items():
    print(f"{k}: {v}")

import json

demo_in = [[4,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
       [9,4,4,4,9,4,4,9,9,9,4,4,4,9,4],
       [4,4,4,4,4,4,4,4,4,4,4,4,4,9,4],
       [9,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
       [4,4,4,4,4,4,4,4,4,4,4,4,4,9,4],
       [4,4,4,4,4,4,4,4,4,4,4,4,4,9,4],
       [9,4,4,4,4,4,4,4,4,4,4,4,4,9,4],
       [9,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
       [9,4,4,4,4,4,4,4,4,4,4,4,4,4,4],
       [4,4,4,4,4,4,4,4,4,4,4,4,4,9,4],
       [4,4,4,4,4,4,4,4,4,4,4,4,4,9,4],
       [9,4,9,4,4,4,4,4,4,9,4,4,4,9,4]]

# All 4-cells with their 9-neighbor count
cells_with_9_neighbors = []
h, w = len(demo_in), len(demo_in[0])
for r in range(h):
    for c in range(w):
        if demo_in[r][c] == 4:
            count = 0
            positions = []
            for dr in [-1, 0, 1]:
                for dc in [-1, 0, 1]:
                    if dr == 0 and dc == 0:
                        continue
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and demo_in[nr][nc] == 9:
                        count += 1
                        positions.append((nr, nc))
            if count > 0:
                cells_with_9_neighbors.append((r, c, count, positions))

print(f"4-cells with 9-neighbors: {len(cells_with_9_neighbors)}")

# Now compare: which ones changed, which didn't
changed = set()
for r in range(h):
    for c in range(w):
        if demo_in[r][c] == 4 and demo_out[r][c] == 2:
            changed.add((r, c))

print("\nCells with 9-neighbors that CHANGED to 2:")
for r, c, count, pos in cells_with_9_neighbors:
    if (r, c) in changed:
        print(f"  ({r},{c}): {count} 9-neighbors at {pos}")

print("\nCells with 9-neighbors that STAYED as 4:")
for r, c, count, pos in cells_with_9_neighbors:
    if (r, c) not in changed:
        print(f"  ({r},{c}): {count} 9-neighbors at {pos}")

print("\nAll changed 4-cells (regardless of 9-neighbors):")
for r in range(h):
    for c in range(w):
        if demo_in[r][c] == 4 and (r, c) in changed:
            # Count how many different 9 positions surround this cell (row or col)
            row_9s = sum(1 for cc in range(w) if demo_in[r][cc] == 9)
            col_9s = sum(1 for rr in range(h) if demo_in[rr][c] == 9)
            print(f"  ({r},{c}): row has {row_9s} 9s, col has {col_9s} 9s")

