    return any(grid[rr][c] == 9 for rr in range(r-1, -1, -1)) and any(grid[rr][c] == 9 for rr in range(r+1, H))

def row_int(r, grid, W):
    return sum(1 for cc in range(1, W-1) if grid[r][cc] == 9)

def col_int(c, grid, H):
    return sum(1 for rr in range(1, H-1) if grid[rr][c] == 9)

